package com.aistudyassistance.backend.project;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/projects/{projectId}/milestones")public class MilestoneController{final MilestoneRepository r;MilestoneController(MilestoneRepository r){this.r=r;}@GetMapping List<Milestone>all(@PathVariable Long projectId){return r.findByProjectId(projectId);}@PostMapping@ResponseStatus(HttpStatus.CREATED)Milestone add(@PathVariable Long projectId,@RequestBody Milestone m){m.id=null;m.projectId=projectId;return r.save(m);}@PutMapping("/{id}")Milestone put(@PathVariable Long projectId,@PathVariable Long id,@RequestBody Milestone m){m.id=id;m.projectId=projectId;return r.save(m);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void del(@PathVariable Long id){r.deleteById(id);}}
